using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using VisionFramework;
using VisionPluginContracts;
using Brushes=System.Windows.Media.Brushes;
using Color=System.Windows.Media.Color;
using ColorConverter=System.Windows.Media.ColorConverter;
using W=System.Windows.Controls;
namespace VisionPlugins.ImageSource;

public sealed class ImageBufferWindow:Window {
 readonly ToolEditorContext context; bool running,continuous,closed; readonly W.Button once=new(){Name="ExecuteBuffer",Content="执行",Width=66,Height=25,Margin=new Thickness(3,0,0,0)}; readonly W.Button loop=new(){Name="ContinuousBuffer",Content="连续执行",Width=66,Height=25};
 public ImageBufferWindow(ToolEditorContext context){this.context=context;Width=420;Height=500;WindowStyle=WindowStyle.None;ResizeMode=ResizeMode.NoResize;WindowStartupLocation=WindowStartupLocation.CenterOwner;Background=Brush("#F2F3F5");FontFamily=new("Microsoft YaHei UI");FontSize=14;
  var root=new W.Grid();root.RowDefinitions.Add(new(){Height=new GridLength(context.Mode==ToolEditorMode.Desktop?34:0)});root.RowDefinitions.Add(new());root.RowDefinitions.Add(new(){Height=new GridLength(32)});var title=new W.DockPanel{Background=Brush("#242424")};var close=new W.Button{Name="CloseBuffer",Content="×",Width=44,FontSize=23,Background=Brushes.Transparent,Foreground=Brushes.LightGray,BorderThickness=new Thickness(0)};close.Click+=(_,_)=>Close();W.DockPanel.SetDock(close,W.Dock.Right);title.Children.Add(close);title.Children.Add(new W.TextBlock{Text=(context.DisplayIndex is int i?i+" ":"")+context.Node.Name,Foreground=Brushes.White,FontWeight=FontWeights.Bold,VerticalAlignment=VerticalAlignment.Center,Margin=new Thickness(10,0,0,0)});title.MouseLeftButtonDown+=(_,_)=>DragMove();root.Children.Add(title);
  var rows=new W.StackPanel{Margin=new Thickness(32,18,34,14)};rows.Children.Add(Header("图像输入"));rows.Children.Add(Link("输入源","InputImage",DataKind.Image));rows.Children.Add(new W.Border{Height=1,Background=Brush("#D7D7D7"),Margin=new Thickness(0,5,0,16)});rows.Children.Add(Header("缓存设置"));rows.Children.Add(Link("缓存使能","RefreshFlag",DataKind.Integer));rows.Children.Add(Link("缓存数量","BufferCount",DataKind.Integer));W.Grid.SetRow(rows,1);root.Children.Add(rows);var commands=new W.StackPanel{Orientation=W.Orientation.Horizontal,HorizontalAlignment=System.Windows.HorizontalAlignment.Right,Margin=new Thickness(0,3,16,3)};loop.Click+=async(_,_)=>{if(continuous){continuous=false;loop.Content="连续执行";return;}if(running)return;continuous=true;loop.Content="停止";do{await Execute();if(continuous&&!closed)await Task.Delay(1);}while(continuous&&!closed);loop.Content="连续执行";once.IsEnabled=true;};once.Click+=async(_,_)=>await Execute();commands.Children.Add(loop);commands.Children.Add(once);var confirm=new W.Button{Name="ConfirmBuffer",Content="确定",Width=66,Height=25,Margin=new Thickness(3,0,0,0)};confirm.Click+=(_,_)=>Close();commands.Children.Add(confirm);W.Grid.SetRow(commands,2);root.Children.Add(commands);Closed+=(_,_)=>{closed=true;continuous=false;};Content=new W.Border{BorderBrush=Brush("#F34A35"),BorderThickness=new Thickness(0,context.Mode==ToolEditorMode.Desktop?1:0,0,0),Child=root};
 }
 async Task Execute(){if(running||closed)return;running=true;once.IsEnabled=false;try{await context.Run(context.Node.Parameters.ToDictionary(p=>p.Key,p=>p.Value.Clone()));}catch(Exception ex){continuous=false;System.Windows.MessageBox.Show(this,ex.Message,"执行失败");}finally{running=false;once.IsEnabled=!continuous;}}
 static SolidColorBrush Brush(string color)=>new((Color)ColorConverter.ConvertFromString(color));
 static W.TextBlock Header(string text)=>new(){Text=text,FontWeight=FontWeights.Bold,Margin=new Thickness(0,2,0,12)};
 FrameworkElement Link(string caption,string port,DataKind kind){
  var row=new W.Grid{Height=35};row.ColumnDefinitions.Add(new(){Width=new GridLength(90)});row.ColumnDefinitions.Add(new());row.Children.Add(new W.TextBlock{Text=caption,VerticalAlignment=VerticalAlignment.Center,Foreground=Brush("#62676C")});
  var field=new W.Grid{Height=31};var text=new W.TextBox{Name="Value"+port,Text=context.SubscriptionLabel?.Invoke(port,false)??"",IsReadOnly=kind==DataKind.Image||context.SetInputInteger is null,BorderBrush=Brush("#C8C8C8"),Background=kind==DataKind.Image?Brushes.White:Brushes.Transparent,Padding=new Thickness(6,0,28,0),VerticalContentAlignment=VerticalAlignment.Center,Foreground=Brush("#62676C")};string applied=text.Text;
  void Commit(){if(text.IsReadOnly||text.Text==applied)return;string current=text.Text.Trim();if(current.Length==0){context.SetInputInteger?.Invoke(port,null);text.Text="";}else if(int.TryParse(current,System.Globalization.NumberStyles.Integer,System.Globalization.CultureInfo.InvariantCulture,out int value)){context.SetInputInteger?.Invoke(port,value);text.Text=value.ToString(System.Globalization.CultureInfo.InvariantCulture);}else text.Text=applied;applied=text.Text;}
  text.LostKeyboardFocus+=(_,_)=>Commit();text.KeyDown+=(_,e)=>{if(e.Key==System.Windows.Input.Key.Enter){Commit();e.Handled=true;}};field.Children.Add(text);
  var button=new W.Button{Name="Subscribe"+port,Height=29,Width=28,HorizontalAlignment=System.Windows.HorizontalAlignment.Right,Background=Brushes.Transparent,BorderThickness=new Thickness(0),Padding=new Thickness(4),ToolTip="订阅参数"};button.Content=kind==DataKind.Image?new W.TextBlock{Text="▾",Foreground=Brush("#CDB9A9"),HorizontalAlignment=System.Windows.HorizontalAlignment.Right}:new W.Image{Source=new BitmapImage(new Uri("pack://application:,,,/VisionPlugins.ImageSource;component/Resources/ic_btn_link_normal.png")),Width=18,Height=18};button.Click+=(_,_)=>{Commit();context.PickSubscription?.Invoke(this,port,false,kind);text.Text=context.SubscriptionLabel?.Invoke(port,false)??"";applied=text.Text;};field.Children.Add(button);W.Grid.SetColumn(field,1);row.Children.Add(field);return row;
 }
}